import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import Logo from '../assets/logo.png';
// css link
import '../styles/auth.css';
import { loginRoute } from '../utils/APIRoutes';

// Function
function Login() {
  const navigate = useNavigate();
  // State
  const [values, setValues] = useState({
    username: '',
    password: '',
  });



  
  // Handle Submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (handleValidation()) {
      const { password, username } = values;
      const { data } = await axios.post(loginRoute, {
        username,
        password,
      });
      if (data.status === false) {
        displayError(data.element, data.msg);
      }
      console.log(data.users);
      if (data.status === true) {
        delete data.users.password;
        localStorage.setItem('chaxapp-xchat', JSON.stringify(data.users));
        navigate('/');
      }
    }
  };
  // HandleValidation
  function handleValidation() {
    // Clear Values
    document.querySelectorAll('input').forEach((input) => {
      input.classList.remove('error');
    });
    document.querySelectorAll('.error_div').forEach((error) => {
      error.textContent = ' ';
    });

    const { password, username } = values;
    // Username
    if (username.length === '')
      return displayError('username', 'username is required');
    // Mobile Number
    // if (mobileNumber.length !== 10)
    //   return displayError('mobileNumber', 'mobile number must have 10 digits');
    // if (/[a-zA-Z]/g.test(mobileNumber))
    //   return displayError('mobileNumber', 'mobile number should be digits');
    // Password
    if (password.length === '')
      return displayError('password', 'password is required');
    return true;
  }
  // Display Error
  function displayError(name, txt) {
    console.log(name, txt);
    const element = document.querySelector(`[name = ${name}]`);
    const errorDiv = document.querySelector(`[name = ${name}] ~ .error_div`);
    element.classList.add('error');
    errorDiv.textContent = `${txt}`;
    return false;
  }
  // Handle Change
  const handleChange = (e) => {
    setValues({ ...values, [e.target.name]: e.target.value });
  };

  // Return
  return (
    <div id="register_component">
      <form onSubmit={(e) => handleSubmit(e)}>
        {/* Logo and title */}
        <div className="logo">
          <img src={Logo} alt="Brand Logo" />
          <h2>chaxapp</h2>
        </div>
        {/* Heading */}
        <div className="heading">
          <h3>Connect us</h3>
        </div>
        {/* User div */}
        <div className="input_div">
          <input
            type="text"
            name="username"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>username / Mobile number</label>
          <div className="error_div"></div>
        </div>
        {/* Password div */}
        <div className="input_div">
          <input
            type="password"
            name="password"
            placeholder=" "
            onChange={(e) => handleChange(e)}
          />
          <label>Password</label>
          <div className="error_div"></div>
        </div>
        {/* Login buttom */}
        <button type="submit">Login</button>
        <div className="general" name="general"></div>
        {/* hrd */}
        <div className="or">
          <span></span>
          <p>or</p>
          <span></span>
        </div>
        {/* login */}
        <div className="login_div">
          <p>Don't have an account ?</p>
          <Link className=".link" to="/register">
            sign up
          </Link>
        </div>
      </form>
    </div>
  );
}

export default Login;
